using System;using System.Windows.Forms;
namespace LoopFive {
 public static class FxEditor {
  public static bool UsesAmount(string t){return Has(t,"SYNTH|RADIO|G2B|SUSTAINER|AUTO RIFF|PITCH BEND|ELECTRIC|PREAMP|DIST|ISOLATOR|MANUAL PAN|STEREO ENHANCE|GRANULAR DELAY|WARP|TWIST|VINYL FLICK");}
  public static bool UsesFeedback(string t){return Has(t,"LPF|BPF|HPF|PHASER|FLANGER|SYNTH|DELAY|PANNING DELAY|REVERSE DELAY|MOD DELAY|TAPE ECHO|GRANULAR DELAY|WARP|TWIST");}
  public static bool UsesClock(string t){return Has(t,"LPF|BPF|HPF|PHASER|FLANGER|AUTO RIFF|ISOLATOR|AUTO PAN|TREMOLO|VIBRATO|PATTERN SLICER|STEP SLICER|DELAY|PANNING DELAY|REVERSE DELAY|MOD DELAY|TAPE ECHO|GRANULAR DELAY|ROLL|BEAT REPEAT|BEAT SCATTER|BEAT SHIFT|CHORUS|REVERSE REVERB");}
  public static bool IsPitch(string t){return Has(t,"TRANSPOSE|PITCH BEND|HRM MANUAL|HRM AUTO (M)|ELECTRIC");}
  static bool Has(string type,string list){return ("|"+list+"|").Contains("|"+type+"|");}
  static string B(string es,string en){Language.Register(es,en);return es;}
  public static void Build(EditorGrid g,FxConfig f,bool input,Action<Action> change,Action rebuild){if(f.Detail==null)f.Detail=new FxDetail();FxDetail d=f.Detail;string t=f.Type;
   g.Number(B("Nivel del efecto (%)","Effect level (%)"),d.Level*100,0,200,delegate(float v){change(delegate{d.Level=v/100;});},0);
   if(Has(t,"LPF|BPF|HPF|SYNTH|RING.MOD"))g.Number(B(t=="RING.MOD"?"Frecuencia portadora (Hz)":"Corte / centro del filtro (Hz)",t=="RING.MOD"?"Carrier frequency (Hz)":"Filter cutoff / center (Hz)"),d.Cutoff,20,18000,delegate(float v){change(delegate{d.Cutoff=v;});},0);
   if(Has(t,"LPF|BPF|HPF|PHASER|FLANGER|ISOLATOR|AUTO PAN|TREMOLO|VIBRATO|PATTERN SLICER|STEP SLICER|MOD DELAY|CHORUS")){g.Number(B("Profundidad de modulación (%)","Modulation depth (%)"),d.Depth*100,0,100,delegate(float v){change(delegate{d.Depth=v/100;});},0);g.Number(B("Velocidad libre (Hz)","Free rate (Hz)"),d.RateHz,.01f,20,delegate(float v){change(delegate{d.RateHz=v;});},2);}
   if(Has(t,"LPF|BPF|HPF|PHASER|FLANGER|AUTO PAN|TREMOLO|ISOLATOR|RING.MOD"))g.Choice(B("Forma de modulación","Modulation waveform"),new string[]{"Sine","Square","Triangle","Sine / oscillator","Detune"},d.Waveform,delegate(int v){change(delegate{d.Waveform=v;});});
   if(t=="AUTO RIFF")g.Number(B("Velocidad de frase libre (ciclos/s)","Free phrase rate (cycles/s)"),d.RateHz,.01f,20,delegate(float v){change(delegate{d.RateHz=v;});},2);
   if(t=="LO-FI"){g.Number(B("Resolución (bits)","Bit depth (bits)"),d.Bits,1,24,delegate(float v){change(delegate{d.Bits=(int)v;});},0);g.Number(B("Divisor de muestreo (1 = sin reducción)","Sample-rate divisor (1 = no reduction)"),d.SampleDivisor,1,32,delegate(float v){change(delegate{d.SampleDivisor=(int)v;});},0);}
   if(UsesClock(t)){float[] beats={.0625f,.125f,.25f,.5f,1,2,4,8,16,.375f,.75f,1.5f,3,1f/6,1f/3,2f/3};string[] notes={"1/64","1/32","1/16","1/8","1/4","1/2","1 bar","2 bars","4 bars","1/16 dotted","1/8 dotted","1/4 dotted","1/2 dotted","1/16 triplet","1/8 triplet","1/4 triplet"};int selected=0;for(int i=0;i<beats.Length;i++)if(Math.Abs(f.Beats-beats[i])<.0001)selected=i;g.Choice(B("División musical (activa sincronización)","Note division (enables sync)"),notes,selected,delegate(int v){change(delegate{f.Beats=beats[v];f.Sync=true;});rebuild();});}
   if(Has(t,"DELAY|PANNING DELAY|REVERSE DELAY|MOD DELAY|TAPE ECHO|ROLL|BEAT REPEAT|BEAT SCATTER"))g.Number(B("Tiempo libre (ms)","Free time (ms)"),d.TimeMs,1,2000,delegate(float v){change(delegate{d.TimeMs=v;});},1);
   if(Has(t,"DELAY|PANNING DELAY|REVERSE DELAY|MOD DELAY|TAPE ECHO|CHORUS|REVERB|GATE REVERB|REVERSE REVERB")){g.Number(B("Corte de graves (Hz, 0 = plano)","Low cut (Hz, 0 = flat)"),d.LowCut,0,12000,delegate(float v){change(delegate{d.LowCut=v;});},0);g.Number(B("Corte de agudos (Hz, 0 = plano)","High cut (Hz, 0 = flat)"),d.HighCut,0,20000,delegate(float v){change(delegate{d.HighCut=v;});},0);}
   if(Has(t,"REVERB|GATE REVERB|REVERSE REVERB")){g.Number(B("Duración de reverb (s)","Reverb time (s)"),d.ReverbSeconds,.1f,10,delegate(float v){change(delegate{d.ReverbSeconds=v;});},2);g.Number("Pre-delay (ms)",d.PreDelayMs,0,500,delegate(float v){change(delegate{d.PreDelayMs=v;});},0);}
   if(Has(t,"SUSTAINER|DYNAMICS|SLOW GEAR|ROBOT|VOCODER|OSC VOC (M)|OSC BOT|PATTERN SLICER|STEP SLICER|FREEZE|GATE REVERB")){g.Number(B("Ataque / subida (ms)","Attack / rise (ms)"),d.AttackMs,1,2000,delegate(float v){change(delegate{d.AttackMs=v;});},0);g.Number(B("Recuperación / caída (ms)","Release / fall (ms)"),d.ReleaseMs,5,5000,delegate(float v){change(delegate{d.ReleaseMs=v;});},0);}
   if(Has(t,"SUSTAINER|DYNAMICS|SLOW GEAR|GATE REVERB"))g.Number(B("Umbral (dBFS)","Threshold (dBFS)"),d.ThresholdDb,-60,0,delegate(float v){change(delegate{d.ThresholdDb=v;});},1);
   if(t=="DYNAMICS")g.Number(B("Relación de compresión","Compression ratio"),d.Ratio,1,20,delegate(float v){change(delegate{d.Ratio=v;});},1);
   if(t=="VOCODER"){g.Choice(B("Portadora del vocoder","Vocoder carrier"),new string[]{B("Pista 1","Track 1"),B("Pista 2","Track 2"),B("Pista 3","Track 3"),B("Pista 4","Track 4"),B("Pista 5","Track 5"),B("Entrada izquierda","Left input"),B("Entrada derecha","Right input")},d.Carrier,delegate(int v){change(delegate{d.Carrier=v;});});g.Note(B("La pista portadora debe estar reproduciéndose. Se toma antes del fader: puedes bajar su volumen para escuchar sólo la voz procesada. Una portadora vacía produce silencio con mezcla al 100%.","The carrier track must be playing. It is tapped before the fader, so you can turn its volume down to hear only the processed voice. An empty carrier produces silence at 100% wet."));}
   if(Has(t,"ROBOT|VOCODER|OSC VOC (M)|OSC BOT")){g.Number(B("Sensibilidad del modulador (%)","Modulator sensitivity (%)"),d.ModSensitivity*100,10,1000,delegate(float v){change(delegate{d.ModSensitivity=v/100;});},0);if(t!="VOCODER"){g.Number(B("Nota del oscilador (MIDI)","Oscillator note (MIDI)"),f.Note,12,120,delegate(float v){change(delegate{f.Note=(int)v;});},0);g.Choice(B("Onda del oscilador","Oscillator waveform"),new string[]{"Saw","Square","Triangle","Sine","Detune saw"},d.Waveform,delegate(int v){change(delegate{d.Waveform=v;});});}if(t=="OSC VOC (M)")g.Note(B("Recibe la nota de un teclado MIDI. Sin notas, la voz procesada se desvanece según Release.","Receives pitch from a MIDI keyboard. With no notes, the processed voice fades according to Release."));}
   if(t=="EQ"){g.Number(B("Graves (dB)","Bass (dB)"),d.EqLow,-20,20,delegate(float v){change(delegate{d.EqLow=v;});},1);g.Number(B("Medios bajos (dB)","Low mids (dB)"),d.EqLowMid,-20,20,delegate(float v){change(delegate{d.EqLowMid=v;});},1);g.Number(B("Medios altos (dB)","High mids (dB)"),d.EqHighMid,-20,20,delegate(float v){change(delegate{d.EqHighMid=v;});},1);g.Number(B("Agudos (dB)","Treble (dB)"),d.EqHigh,-20,20,delegate(float v){change(delegate{d.EqHigh=v;});},1);g.Number(B("Cruce de medios bajos (Hz)","Low-mid crossover (Hz)"),d.EqLowMidHz,20,10000,delegate(float v){change(delegate{d.EqLowMidHz=v;});},0);g.Number(B("Cruce de medios altos (Hz)","High-mid crossover (Hz)"),d.EqHighMidHz,20,10000,delegate(float v){change(delegate{d.EqHighMidHz=v;});},0);}
   if(t=="ISOLATOR")g.Choice(B("Banda a atenuar","Band to attenuate"),new string[]{"LOW","MID","HIGH"},d.Direction,delegate(int v){change(delegate{d.Direction=v;});});
   if(Has(t,"PATTERN SLICER|STEP SLICER")){g.Number(B("Duración activa del paso (%)","Step duty (%)"),d.Duty*100,1,99,delegate(float v){change(delegate{d.Duty=v/100;});},0);if(t=="PATTERN SLICER")g.Number(B("Patrón propio (1–20)","Original pattern (1–20)"),d.Pattern+1,1,20,delegate(float v){change(delegate{d.Pattern=(int)v-1;});},0);g.Note(B("En STEP SLICER los valores del editor de 16 pasos controlan directamente el nivel de cada corte.","In STEP SLICER the 16-step editor directly controls the level of each slice."));}
   if(Has(t,"ROLL|BEAT REPEAT"))g.Choice(B("Dirección de repetición","Repeat direction"),new string[]{B("Adelante","Forward"),B("Inversa","Reverse"),B("Alternada","Alternating")},d.Direction,delegate(int v){change(delegate{d.Direction=v;});});
   if(!input)g.Choice(B("Aplicar este efecto a","Apply this effect to"),new string[]{B("Destino global de la cadena","Global chain target"),B("Sólo pista 1","Track 1 only"),B("Sólo pista 2","Track 2 only"),B("Sólo pista 3","Track 3 only"),B("Sólo pista 4","Track 4 only"),B("Sólo pista 5","Track 5 only")},MaskIndex(d.InsertMask),delegate(int v){change(delegate{d.InsertMask=v==0?0:1<<(v-1);});});
  }
  static int MaskIndex(int mask){for(int i=0;i<5;i++)if(mask==(1<<i))return i+1;return 0;}
 }
}
